# uv run marimo edit notebooks/csv_explorer.py で開く。
"""時系列CSVの汎用ビューア。

複数のCSVを読み込み、中身から時刻列と数値列を検出して、
選んだ列だけを重ねて描く。次の状況を想定している。

  - ファイルごとに記録の開始時刻が違う
  - ファイルごとにサンプリング周期が違う（1分 / 5分 / 不定）
  - 収録機器の時計がずれていて、系列どうしの時刻が合っていない
  - 欠測行や重複行がある

時計のずれは、相互相関からラグを推定して手動で補正できるようにしてある。
"""

import marimo

__generated_with = "0.24.0"
app = marimo.App(width="medium")


@app.cell
def _():
    import marimo as mo
    return (mo,)


@app.cell
def _(mo):
    mo.md(
        """
        # 時系列CSVビューア

        CSVを選ぶ → 列を選ぶ → 描く、だけのノートブック。
        列の意味は決め打ちせず、中身から推定する。

        ファイルごとに開始時刻や周期がずれていても扱えるよう、
        **時刻オフセットの補正**と**共通期間の抽出**を入れてある。
        """
    )
    return


@app.cell
def _(mo):
    mo.md("""## 1. 読み込むCSVを選ぶ""")
    return


@app.cell
def _(mo):
    from pathlib import Path

    # 探しにいくディレクトリ。別の場所を見たいときはここを書き換える。
    _default_dir = Path(__file__).resolve().parent.parent / "data"

    data_dir_ui = mo.ui.text(
        value=str(_default_dir), label="データディレクトリ", full_width=True)
    data_dir_ui
    return Path, data_dir_ui


@app.cell
def _(Path, data_dir_ui, mo):
    # ディレクトリ直下のCSVを列挙する（サブディレクトリは見ない）
    _dir = Path(data_dir_ui.value).expanduser()
    csv_paths = sorted(_dir.glob("*.csv")) if _dir.is_dir() else []

    file_picker = mo.ui.multiselect(
        options={p.name: str(p) for p in csv_paths},
        # 既定では全部読み込む。重いファイルがあるときは絞る。
        value=[p.name for p in csv_paths],
        label="読み込むCSV",
    )

    mo.vstack([
        mo.md(f"`{_dir}` に **{len(csv_paths)}件** のCSVが見つかった。")
        if csv_paths else mo.md(f"`{_dir}` にCSVが見つからない。パスを確認すること。"),
        file_picker,
    ])
    return csv_paths, file_picker


@app.cell
def _(mo):
    mo.md(
        """
        ## 2. 読み込みと列の推定

        時刻列は、まず名前で探し、見つからなければ「日時としてパースできるか」で判断する。
        それ以外の列は数値に変換できるものだけを残す（文字列のステータス列などは捨てる）。
        """
    )
    return


@app.cell
def _():
    import re

    import numpy as np
    import pandas as pd

    # 時刻列にありがちな名前。表記ゆれに備えて部分一致で見る。
    TIME_NAME_HINTS = ["timestamp", "datetime", "date_time", "time", "date",
                       "日時", "日付", "時刻", "計測日時", "記録日時"]

    def parse_datetime(series):
        """列を日時に変換する。9割読めなければ時刻列ではないとみなして None を返す。

        yyyy/m/dd、yyyy-mm-dd、Excelが吐く形式などが混ざっていても読めるように、
        pandas の推論に任せたうえで成功率で判定する。
        """
        parsed = pd.to_datetime(series, errors="coerce", format="mixed", dayfirst=False)
        return None if parsed.notna().mean() < 0.9 else parsed

    def find_time_column(df):
        """時刻列の名前を返す。名前で見つからなければ中身で探す。"""
        for col in df.columns:
            name = str(col).strip().lower().replace(" ", "")
            if any(h in name for h in TIME_NAME_HINTS) and parse_datetime(df[col]) is not None:
                return col
        for col in df.columns:
            if parse_datetime(df[col]) is not None:
                return col
        return None

    def read_csv_any(path):
        """文字コードが分からないCSVを読む。UTF-8で駄目ならShift-JIS系を試す。"""
        last_error = None
        for enc in ["utf-8-sig", "utf-8", "cp932", "shift_jis"]:
            try:
                return pd.read_csv(path, encoding=enc)
            except UnicodeDecodeError as exc:
                last_error = exc
        raise ValueError(f"文字コードを判定できない: {path}") from last_error

    def load_timeseries(path):
        """CSVを時刻インデックスの数値DataFrameにする。読めない場合は例外を返さず None。"""
        df = read_csv_any(path)
        time_col = find_time_column(df)
        if time_col is None:
            return None, None

        ts = pd.to_datetime(df[time_col], errors="coerce", format="mixed", dayfirst=False)
        values = df.drop(columns=[time_col]).apply(pd.to_numeric, errors="coerce")
        values = values.dropna(axis=1, how="all")   # 数値がひとつも無い列は捨てる

        out = values.set_index(ts)
        out = out[out.index.notna()]                    # 時刻が読めなかった行を捨てる
        out = out[~out.index.duplicated(keep="first")]  # 同一時刻の重複を1つに
        return out.sort_index(), time_col

    def estimate_interval(index):
        """サンプリング周期を推定する。最頻値を使うので欠測があってもぶれない。"""
        if len(index) < 3:
            return None
        deltas = pd.Series(index).diff().dropna()
        if deltas.empty:
            return None
        return deltas.mode().iloc[0]

    # ---- 単位の推定 ----------------------------------------------------------
    # 値のスケールが違う列を1枚に重ねると読めないので、単位ごとに段を分ける。
    UNIT_PATTERNS = [
        (r"\[([^\]]+)\]", 1),      # [℃] や [kW]
        (r"\(([^)]+)\)", 1),       # (degC)
        (r"（([^）]+)）", 1),       # 全角括弧
    ]
    UNIT_KEYWORDS = ["degc", "℃", "kwh", "kw", "wh", "w", "%", "rh", "pa",
                     "m3/h", "ppm", "lux", "a", "v"]

    def guess_unit(colname):
        """列名から単位を推定する。分からなければ 'その他'。"""
        name = str(colname)
        for pattern, group in UNIT_PATTERNS:
            m = re.search(pattern, name)
            if m:
                return m.group(group).strip()
        # 末尾が _degC のような形式
        tail = re.split(r"[_\s\-]", name)[-1].lower()
        for kw in UNIT_KEYWORDS:
            if tail == kw:
                return kw
        for kw in UNIT_KEYWORDS:
            if kw in name.lower():
                return kw
        return "その他"

    def normalize_unit(unit):
        """degC と ℃ のような表記ゆれを1つにまとめる。"""
        u = str(unit).strip().lower()
        if u in ("degc", "℃", "°c", "c"):
            return "degC"
        if u in ("kw",):
            return "kW"
        if u in ("kwh",):
            return "kWh"
        if u in ("%", "rh"):
            return "%"
        return unit

    return (
        TIME_NAME_HINTS,
        estimate_interval,
        find_time_column,
        guess_unit,
        load_timeseries,
        normalize_unit,
        np,
        parse_datetime,
        pd,
        re,
        read_csv_any,
    )


@app.cell
def _(Path, estimate_interval, file_picker, load_timeseries):
    # 選ばれたCSVをすべて読み込む。読めなかったファイルは理由とともに残す。
    frames, load_errors, meta = {}, {}, {}

    for _path_str in file_picker.value:
        _path = Path(_path_str)
        try:
            _df, _time_col = load_timeseries(_path)
        except Exception as _exc:            # 壊れたファイルで全体が止まらないようにする
            load_errors[_path.name] = str(_exc)
            continue
        if _df is None or _df.empty:
            load_errors[_path.name] = "時刻列または数値列が見つからない"
            continue
        frames[_path.name] = _df
        meta[_path.name] = {
            "time_col": _time_col,
            "start": _df.index.min(),
            "end": _df.index.max(),
            "rows": len(_df),
            "interval": estimate_interval(_df.index),
            "columns": list(_df.columns),
        }
    return frames, load_errors, meta


@app.cell
def _(frames, load_errors, meta, mo, pd):
    def _summary_table():
        """読み込んだファイルの期間・周期・列数を一覧にする。"""
        rows = []
        for name, m in meta.items():
            interval = m["interval"]
            rows.append({
                "ファイル": name,
                "時刻列": m["time_col"],
                "開始": f"{m['start']:%Y-%m-%d %H:%M}",
                "終了": f"{m['end']:%Y-%m-%d %H:%M}",
                "行数": f"{m['rows']:,}",
                "周期": "不明" if interval is None else f"{interval.total_seconds() / 60:.0f}分",
                "数値列数": len(m["columns"]),
            })
        return pd.DataFrame(rows)

    _parts = []
    if frames:
        _parts.append(mo.ui.table(_summary_table(), selection=None))
    if load_errors:
        _parts.append(mo.md("### 読めなかったファイル\n" + "\n".join(
            f"- `{k}`: {v}" for k, v in load_errors.items())))
    if not frames:
        _parts.append(mo.md("読み込めたファイルがない。"))

    mo.vstack(_parts)
    return


@app.cell
def _(mo):
    mo.md(
        """
        ## 3. 時刻のずれを補正する

        収録機器の時計がずれていると、系列を重ねたときに立ち上がりの位置が食い違う。
        ここでファイルごとに時刻をずらして揃える。

        下の「ラグの自動推定」は、2つの系列の**相互相関が最大になるずれ**を返す。
        あくまで目安なので、補正後のグラフで立ち上がりが揃っているか目で確認すること。
        """
    )
    return


@app.cell
def _(frames, mo):
    # ファイルごとの時刻オフセット[分]。正の値はその系列を未来方向へずらす。
    offset_ui = mo.ui.dictionary({
        name: mo.ui.number(-720, 720, value=0, step=1, label=name)
        for name in frames
    })
    mo.vstack([mo.md("**時刻オフセット [分]**"), offset_ui]) if frames else mo.md("")
    return (offset_ui,)


@app.cell
def _(frames, offset_ui, pd):
    # オフセットを適用した系列を作る。以降のセルはこちらを使う。
    shifted = {}
    for _name, _df in frames.items():
        _minutes = float(offset_ui.value.get(_name, 0) or 0)
        _out = _df.copy()
        if _minutes:
            _out.index = _out.index + pd.Timedelta(minutes=_minutes)
        shifted[_name] = _out
    return (shifted,)


@app.cell
def _(mo, shifted):
    # ラグ推定に使う2系列を選ぶ。"ファイル::列" の形で一意にする。
    _options = [f"{name}::{col}" for name, df in shifted.items() for col in df.columns]

    lag_base = mo.ui.dropdown(options=_options, value=_options[0] if _options else None,
                              label="基準にする系列")
    lag_target = mo.ui.dropdown(options=_options,
                                value=_options[-1] if _options else None,
                                label="ずれを調べる系列")
    lag_window = mo.ui.slider(5, 240, value=60, step=5, label="探索するずれの幅 [±分]")

    mo.vstack([mo.hstack([lag_base, lag_target]), lag_window]) if _options else mo.md("")
    return lag_base, lag_target, lag_window


@app.cell
def _(guess_unit, lag_base, lag_target, lag_window, mo, normalize_unit, np, pd, shifted):
    def _series_of(key):
        """'ファイル::列' から Series を取り出す。"""
        name, col = key.split("::", 1)
        return shifted[name][col].dropna()

    def estimate_lag(base_key, target_key, max_lag_minutes):
        """相互相関でラグを推定する。戻り値は分（正なら target が base より遅れている）。

        周期の違うファイルどうしでも比べられるよう、いったん1分グリッドに揃えてから、
        変化の形だけを見たいので差分をとって標準化している。
        """
        a, b = _series_of(base_key), _series_of(target_key)
        # 共通期間だけを使う。期間が重なっていなければ推定できない。
        lo, hi = max(a.index.min(), b.index.min()), min(a.index.max(), b.index.max())
        if lo >= hi:
            return None, "期間が重なっていない", 0.0

        grid = pd.date_range(lo, hi, freq="1min")
        a1 = a.reindex(a.index.union(grid)).interpolate("time").reindex(grid)
        b1 = b.reindex(b.index.union(grid)).interpolate("time").reindex(grid)

        # 絶対値の差ではなく「動き方」を合わせたいので、差分をとってから標準化する
        da, db = a1.diff().fillna(0).to_numpy(), b1.diff().fillna(0).to_numpy()
        if da.std() == 0 or db.std() == 0:
            return None, "どちらかの系列が動いていない", 0.0
        da = (da - da.mean()) / da.std()
        db = (db - db.mean()) / db.std()

        max_lag = int(max_lag_minutes)
        lags = np.arange(-max_lag, max_lag + 1)
        scores = []
        for lag in lags:
            # base[t+lag] と target[t] を対応させる。
            # つまり lag<0 なら target の記録時刻が base より未来にずれている
            # （target 側の時計が進んでいる）ことを意味する。
            if lag > 0:
                x, y = da[lag:], db[:len(db) - lag]
            elif lag < 0:
                x, y = da[:len(da) + lag], db[-lag:]
            else:
                x, y = da, db
            scores.append(np.nan if len(x) < 10 else float(np.dot(x, y) / len(x)))
        scores = np.array(scores)
        if np.all(np.isnan(scores)):
            return None, "比較できる区間が短すぎる", 0.0

        # 室温と電力のように逆向きに動く組み合わせもあるので、相関の絶対値で見る
        best_idx = int(np.nanargmax(np.abs(scores)))
        best = int(lags[best_idx])
        score = float(scores[best_idx])
        note = f"相関 {score:+.3f}" + ("（逆相関）" if score < 0 else "")
        return best, note, abs(score)

    if lag_base.value and lag_target.value and lag_base.value != lag_target.value:
        _lag, _note, _strength = estimate_lag(
            lag_base.value, lag_target.value, lag_window.value)

        if _lag is None:
            _msg = mo.md(f"ラグを推定できない（{_note}）。")
        else:
            # 単位が違う系列どうしのラグには、時計のずれだけでなく
            # 物理的な応答遅れ（電力を入れてから室温が動くまで）が混ざる。
            _unit_base = normalize_unit(guess_unit(lag_base.value.split("::", 1)[1]))
            _unit_targ = normalize_unit(guess_unit(lag_target.value.split("::", 1)[1]))
            _warnings = []
            if _unit_base != _unit_targ:
                _warnings.append(
                    f"単位が違う（{_unit_base} と {_unit_targ}）。"
                    "この値には**物理的な応答遅れ**が含まれるので、時計のずれの推定には使えない。"
                    "時計を揃えたいときは、同じ量を記録した系列どうしで比べること。"
                )
            if _strength < 0.2:
                _warnings.append(
                    f"相関が弱い（|{_strength:.3f}|）。"
                    "この推定値は信用しないこと。期間を絞るか、動きの大きい系列を選び直す。"
                )

            _msg = mo.vstack([
                mo.md(
                    f"""
                    推定ラグ: **{_lag:+d} 分**（{_note}）

                    `{lag_target.value}` は `{lag_base.value}` より **{abs(_lag)}分
                    {'遅れている' if _lag > 0 else '進んでいる'}**。
                    揃えるには、上のオフセット欄で
                    `{lag_target.value.split('::')[0]}` に **{_lag:+d}** を入れる
                    （記録時刻のずれをそのまま打ち消す）。
                    """
                ),
                *[mo.md(w) for w in _warnings],
            ])
    else:
        _msg = mo.md("2つの異なる系列を選ぶとラグを推定する。")
    _msg
    return (estimate_lag,)


@app.cell
def _(mo):
    mo.md("""## 4. 描画する列を選ぶ""")
    return


@app.cell
def _(guess_unit, mo, normalize_unit, shifted):
    # 列の一覧を "ファイル::列" で作る。同名列が複数ファイルにあっても衝突しない。
    _all_keys = [f"{name}::{col}" for name, df in shifted.items() for col in df.columns]

    # 既定の選択。列が多いときに全部描くと潰れるので、
    # 最も行数の多いファイル（＝主たる時系列。日次サマリのような粗い表を避ける）から
    # 最大6列だけ選んでおく。
    if shifted:
        _main = max(shifted, key=lambda n: (len(shifted[n]), len(shifted[n].columns)))
        _default = [f"{_main}::{c}" for c in shifted[_main].columns][:6]
    else:
        _default = []

    column_picker = mo.ui.multiselect(
        options=_all_keys, value=_default, label="描画する列", full_width=True)

    # どの列がどの単位に割り当てられたかを見せる（段の分かれ方の根拠）
    _units = {}
    for _key in _all_keys:
        _unit = normalize_unit(guess_unit(_key.split("::", 1)[1]))
        _units.setdefault(_unit, []).append(_key.split("::", 1)[1])

    mo.vstack([
        column_picker,
        mo.accordion({
            "推定した単位": mo.md("\n".join(
                f"- **{u}**: {', '.join(sorted(set(c)))}" for u, c in sorted(_units.items())))
        }),
    ])
    return (column_picker,)


@app.cell
def _(mo):
    mo.md(
        """
        ## 5. 期間と表示のしかた

        既定では、選んだ列すべてに**データがある期間の共通部分**を出す。
        ファイルによって収録期間が違っても、比較できる範囲だけを見るための既定値である。
        """
    )
    return


@app.cell
def _(column_picker, mo, pd, shifted):
    def _common_span(keys):
        """選ばれた列に共通する期間を返す。共通部分がなければ全体の範囲を返す。"""
        spans = []
        for key in keys:
            name, col = key.split("::", 1)
            s = shifted[name][col].dropna()
            if not s.empty:
                spans.append((s.index.min(), s.index.max()))
        if not spans:
            return None, None
        lo = max(s[0] for s in spans)
        hi = min(s[1] for s in spans)
        if lo >= hi:  # 重なりがない場合は全体を出す（ずれの確認ができるように）
            return min(s[0] for s in spans), max(s[1] for s in spans)
        return lo, hi

    span_lo, span_hi = _common_span(column_picker.value)

    if span_lo is None:
        date_range_ui = mo.ui.date_range(
            start=pd.Timestamp("2000-01-01").date(),
            stop=pd.Timestamp("2100-01-01").date(),
            label="表示する日付")
    else:
        date_range_ui = mo.ui.date_range(
            start=span_lo.date(), stop=span_hi.date(),
            value=(span_lo.date(), span_hi.date()),
            label="表示する日付")

    hour_range_ui = mo.ui.range_slider(
        0, 24, value=[0, 24], step=1, label="時刻で絞る [時]", show_value=True)

    resample_ui = mo.ui.dropdown(
        options={"生データ": "", "1分平均": "1min", "5分平均": "5min",
                 "15分平均": "15min", "1時間平均": "1h"},
        value="生データ", label="リサンプル")

    overlay_ui = mo.ui.switch(value=False, label="単位が違っても1枚に重ねる")

    mo.vstack([date_range_ui, hour_range_ui, mo.hstack([resample_ui, overlay_ui])])
    return date_range_ui, hour_range_ui, overlay_ui, resample_ui, span_hi, span_lo


@app.cell
def _(
    column_picker,
    date_range_ui,
    hour_range_ui,
    pd,
    resample_ui,
    shifted,
):
    def build_selection():
        """選ばれた列を、期間・時刻・リサンプルの条件で切り出してまとめる。"""
        lo = pd.Timestamp(date_range_ui.value[0])
        hi = pd.Timestamp(date_range_ui.value[1]) + pd.Timedelta(days=1)
        h_lo, h_hi = hour_range_ui.value

        out = {}
        for key in column_picker.value:
            name, col = key.split("::", 1)
            s = shifted[name][col].dropna().loc[lo:hi]
            # 時刻での絞り込み。24を指定したときに最終分が落ちないよう < で扱う。
            if (h_lo, h_hi) != (0, 24):
                hours = s.index.hour + s.index.minute / 60
                s = s[(hours >= h_lo) & (hours < h_hi)]
            if resample_ui.value:
                s = s.resample(resample_ui.value).mean().dropna()
            out[key] = s
        return out

    selected = build_selection()
    return build_selection, selected


@app.cell
def _():
    from hvac import use_japanese_font

    # 軸ラベルは英語にしてあるが、凡例には実データの列名がそのまま出る。
    # 実データの列名は日本語なので、フォントを設定しないと豆腐になる。
    use_japanese_font()  # pyplot の import 前に呼ぶ

    import matplotlib
    import matplotlib.pyplot as plt

    matplotlib.rcParams["figure.autolayout"] = True
    matplotlib.rcParams["axes.grid"] = True
    matplotlib.rcParams["grid.alpha"] = 0.3
    return matplotlib, plt


@app.cell
def _(guess_unit, mo, normalize_unit, overlay_ui, plt, selected):
    def plot_selection():
        """選んだ列を描く。単位ごとに段を分ける（重ねる設定なら1枚にする）。"""
        series = {k: v for k, v in selected.items() if not v.empty}
        if not series:
            return None

        if overlay_ui.value:
            groups = {"all": list(series)}
        else:
            groups = {}
            for key in series:
                unit = normalize_unit(guess_unit(key.split("::", 1)[1]))
                groups.setdefault(unit, []).append(key)

        fig, axes = plt.subplots(
            len(groups), 1, figsize=(12, 3.2 * len(groups)), sharex=True, squeeze=False)

        for ax, (unit, keys) in zip(axes[:, 0], groups.items()):
            for key in keys:
                s = series[key]
                # 凡例はファイル名を省いて列名だけにする（長くなりすぎるため）
                ax.plot(s.index, s.to_numpy(), lw=0.9, label=key.split("::", 1)[1])
            ax.set_ylabel(unit if unit != "all" else "value")
            ax.legend(fontsize=7, ncol=3, loc="upper right")
        axes[-1, 0].set_xlabel("time")
        fig.autofmt_xdate()
        return fig

    _fig = plot_selection()
    mo.as_html(_fig) if _fig is not None else mo.md("描画できるデータがない。列や期間を見直すこと。")
    return (plot_selection,)


