"""受領したデータの健全性チェック。

実データはダミーデータと同じ形とはかぎらない。列名、粒度、期間、欠測、単位、
センサの生死のいずれもずれうる。分析を回す前にここで洗い出し、
「気づかないまま間違った数字を出す」ことを防ぐ。

警告は落とすためのものではなく、確認するためのもの。
どれも「これはおかしい」ではなく「これを確かめろ」という意味である。
"""

from __future__ import annotations

from dataclasses import dataclass, field

import numpy as np
import pandas as pd

from hvac.energy import sampling_interval_hours
from hvac.io import (
    find_power_columns,
    map_outdoor_columns,
    map_room_columns,
)

# 室温として現実的な範囲。これを外れたらセンサ異常か単位違いを疑う。
PLAUSIBLE_ROOM_RANGE = (-10.0, 50.0)
PLAUSIBLE_OUTDOOR_RANGE = (-30.0, 55.0)
PLAUSIBLE_HUMIDITY_RANGE = (0.0, 100.0)
# チラー電力[kW]の上限の目安。桁が違えば W 単位で入っている可能性がある。
PLAUSIBLE_POWER_MAX_KW = 2000.0

# 起動時刻を分単位で読むのに必要な粒度。1時間粒度では立ち上がりを追えない。
MAX_INTERVAL_FOR_STARTUP_MIN = 10.0

# 同じ値がこの割合以上続いたら、センサが張り付いている可能性がある。
STUCK_RATIO = 0.5

# 記録の刻みがこれより粗いと、到達判定の許容幅（既定0.5℃）に効いてくる。
QUANTIZATION_WARN_STEP = 0.25

# 始業前に閾値を何回またいだらチャタリングとみなすか。
# 立ち上がりがきれいなら、またぐのは1回だけである。
CHATTERING_CROSSINGS = 6


@dataclass
class DataReport:
    """1つのデータフレームの素性。"""

    name: str
    rows: int
    columns: int
    start: pd.Timestamp | None
    end: pd.Timestamp | None
    interval_minutes: float
    coverage_ratio: float
    duplicated_rows: int
    warnings: list[str] = field(default_factory=list)

    def as_row(self) -> dict:
        return {
            "データ": self.name,
            "行数": self.rows,
            "列数": self.columns,
            "開始": self.start,
            "終了": self.end,
            "粒度 [分]": round(self.interval_minutes, 2),
            "充足率 [%]": round(self.coverage_ratio * 100.0, 1),
            "重複時刻": self.duplicated_rows,
            "警告": len(self.warnings),
        }


def _coverage_ratio(frame: pd.DataFrame, interval_minutes: float) -> float:
    """期間に対して実際に何割の時刻が入っているか。欠測の見当をつける。"""
    if len(frame) < 2 or interval_minutes <= 0:
        return 1.0
    span_minutes = (frame.index.max() - frame.index.min()).total_seconds() / 60.0
    expected = span_minutes / interval_minutes + 1
    return min(len(frame) / expected, 1.0) if expected > 0 else 1.0


def _stuck_columns(frame: pd.DataFrame, columns: list) -> list[str]:
    """値がほとんど動かない列。センサの張り付きか、未接続を疑う。

    設定温度や待機中の電力は動かないのが正常なので、この検査にはかけない。
    正常な値まで警告に挙げると、警告そのものが読まれなくなる。
    """
    stuck = []
    for column in columns:
        values = frame[column].dropna()
        if len(values) < 10:
            continue
        top = values.value_counts(normalize=True)
        if not top.empty and top.iloc[0] >= STUCK_RATIO:
            stuck.append(f"{column}（{top.index[0]} が {top.iloc[0] * 100:.0f}%）")
    return stuck


def _dead_columns(frame: pd.DataFrame, columns: list) -> list[str]:
    """全期間で1つの値しか取らない列。動かないのが正常な列でもこれは異常。"""
    return [str(c) for c in columns if frame[c].dropna().nunique() <= 1]


def quantization_step(values: pd.Series) -> float | None:
    """記録の刻み幅。刻みが見つからなければ None。

    BEMSは室温を 0.5℃ 刻みで記録することがある。刻みが到達判定の許容幅に
    近いと、「到達した瞬間」が刻みの分だけずれ、予冷時間が階段状になる。
    """
    unique = np.unique(np.round(values.dropna().to_numpy(dtype=float), 6))
    if len(unique) < 3:
        return None

    diffs = np.diff(unique)
    diffs = diffs[diffs > 1e-9]
    if len(diffs) == 0:
        return None

    step = float(np.min(diffs))
    ratios = diffs / step
    # 値の差がすべて最小刻みの整数倍なら、その刻みで量子化されている。
    # ノイズが乗っていれば整数倍にはならないので、この検査は通らない。
    if np.allclose(ratios, np.round(ratios), atol=0.01):
        return step
    return None


def _quantized_columns(frame: pd.DataFrame, columns: list) -> list[str]:
    found = []
    for column in columns:
        step = quantization_step(frame[column])
        if step is not None and step >= QUANTIZATION_WARN_STEP:
            found.append(f"{column}（{step:g} 刻み）")
    return found


def threshold_crossings(series: pd.Series, threshold_ratio: float = 0.2) -> int:
    """待機とピークの間に引いた閾値を、何回またいだか。"""
    clean = series.dropna()
    if clean.empty:
        return 0
    standby = clean.quantile(0.05)
    peak = clean.max()
    if peak - standby < 1e-9:
        return 0
    above = clean > (standby + (peak - standby) * threshold_ratio)
    return int((above != above.shift()).sum())


def check_startup_stability(
    power: pd.DataFrame, business_hour: int = 8, threshold_ratio: float = 0.2
) -> list[str]:
    """立ち上がりが閾値付近で震えていないかを見る。

    低出力で長く運転してから本格稼働に入る日は、電力が閾値の上下を往復し、
    「一定時間continuously超えた最初の時刻」を満たすのが遅れる。
    その日は起動検出が実際より遅くなり、「起動時点で既に設定温度に達していた」
    ように見えてしまう。
    """
    columns = find_power_columns(power)
    if not columns:
        return []

    total = power[columns].sum(axis=1)
    morning = total[total.index.hour < business_hour]
    if morning.empty:
        return []

    noisy = []
    for day, series in morning.groupby(morning.index.date):
        crossings = threshold_crossings(series, threshold_ratio)
        if crossings >= CHATTERING_CROSSINGS:
            noisy.append((day, crossings))

    if not noisy:
        return []

    listed = ", ".join(f"{day}（{count}回）" for day, count in noisy[:8])
    more = " ほか" if len(noisy) > 8 else ""
    return [
        f"始業前に電力が起動判定の閾値を何度もまたぐ日が {len(noisy)} 日ある: {listed}{more}。"
        "低出力運転が続いてから本格稼働に入ると起こる。"
        "その日は起動検出が実際より遅くなり、予冷時間が短く見える。"
        "日別の電力波形（ノートブック 01）で検出時刻を目視確認すること。"
    ]


def describe_frame(name: str, frame: pd.DataFrame, kind: str = "") -> DataReport:
    """1つのデータフレームを点検する。`kind` は room / outdoor / power。"""
    warnings: list[str] = []

    if frame.empty:
        return DataReport(name, 0, 0, None, None, 0.0, 0.0, 0, ["データが空である。"])

    # 列の役割で検査を分ける。設定温度と電力は動かない時間があって当たり前。
    if kind == "room":
        measured, expected_constant = map_room_columns(frame)
        measured_columns = list(measured.values())
        constant_columns = list(expected_constant.values())
        range_checks = [(measured_columns, PLAUSIBLE_ROOM_RANGE, "室温")]
    elif kind == "outdoor":
        temperature, humidity = map_outdoor_columns(frame)
        measured_columns = list(temperature.values()) + list(humidity.values())
        constant_columns = []
        range_checks = [
            (list(temperature.values()), PLAUSIBLE_OUTDOOR_RANGE, "外気温"),
            (list(humidity.values()), PLAUSIBLE_HUMIDITY_RANGE, "外気湿度"),
        ]
    else:
        measured_columns = []
        constant_columns = list(frame.columns)
        range_checks = []

    interval_minutes = sampling_interval_hours(frame) * 60.0
    coverage = _coverage_ratio(frame, interval_minutes)
    duplicated = int(frame.index.duplicated().sum())

    if coverage < 0.99:
        warnings.append(
            f"時刻の充足率が {coverage * 100:.1f}%。期間内に欠測がある。"
            "日別の集計で、日によって件数が違わないか確認すること。"
        )
    if duplicated:
        warnings.append(f"重複した時刻が {duplicated} 件ある（読み込み時に先勝ちで落としている）。")

    all_nan = [c for c in frame.columns if frame[c].dropna().empty]
    if all_nan:
        warnings.append(f"全て欠測の列がある: {', '.join(map(str, all_nan))}")

    stuck = _stuck_columns(frame, measured_columns)
    if stuck:
        warnings.append(
            f"計測値がほとんど動かない列がある（センサ張り付きの可能性）: {'; '.join(stuck)}"
        )

    dead = _dead_columns(frame, measured_columns + constant_columns)
    if dead:
        warnings.append(
            f"全期間で値が1つしかない列がある（未接続の可能性）: {', '.join(dead)}"
        )

    quantized = _quantized_columns(frame, measured_columns)
    if quantized:
        warnings.append(
            f"値が粗い刻みで記録されている列がある: {', '.join(quantized)}。"
            "到達判定の許容幅（既定 0.5℃）と同じ桁なら、到達時刻が刻みの分だけずれ、"
            "予冷時間が階段状になる。許容幅の設定を見直すこと。"
        )

    nan_ratio = frame.isna().mean()
    heavy = [f"{c}（{r * 100:.1f}%）" for c, r in nan_ratio.items() if r > 0.05]
    if heavy:
        warnings.append(f"欠測が5%を超える列がある: {', '.join(heavy)}")

    if kind == "power":
        if interval_minutes > MAX_INTERVAL_FOR_STARTUP_MIN:
            warnings.append(
                f"粒度が {interval_minutes:.0f} 分。起動時刻を分単位で読むには粗い。"
                "詳細データ（分粒度）を使うこと。通年データは月別の傾向把握に使う。"
            )
        maximum = float(frame.max(numeric_only=True).max())
        if maximum > PLAUSIBLE_POWER_MAX_KW:
            warnings.append(
                f"電力の最大値が {maximum:,.0f}。kW ではなく W で入っている可能性がある。"
            )
        if float(frame.min(numeric_only=True).min()) < 0:
            warnings.append("電力に負の値がある。逆潮流か、電力以外の列を拾っている可能性がある。")

    for columns, (low, high), label in range_checks:
        for column in columns:
            values = frame[column].dropna()
            if values.empty:
                continue
            if values.min() < low or values.max() > high:
                warnings.append(
                    f"{label} `{column}` の値域が {values.min():.1f}〜{values.max():.1f} で、"
                    f"想定 ({low}〜{high}) を外れる。単位（℉など）かセンサ異常を疑う。"
                )

    return DataReport(
        name=name,
        rows=len(frame),
        columns=len(frame.columns),
        start=frame.index.min(),
        end=frame.index.max(),
        interval_minutes=interval_minutes,
        coverage_ratio=coverage,
        duplicated_rows=duplicated,
        warnings=warnings,
    )


def check_column_mapping(
    room: pd.DataFrame, outdoor: pd.DataFrame | None, power: pd.DataFrame | None
) -> tuple[dict[str, dict], list[str]]:
    """列がどう解釈されたかと、そこから出る警告を返す。"""
    warnings: list[str] = []

    room_columns, setpoint_columns = map_room_columns(room)
    mapping = {
        "室温": room_columns,
        "設定温度": setpoint_columns,
    }

    if not room_columns:
        warnings.append("室温列を1つも特定できない。列名の推定規則を実データに合わせること。")
    if not setpoint_columns:
        warnings.append(
            "設定温度列を特定できない。到達判定ができないため、"
            "設定温度を別途与えるか列名の推定規則を直すこと。"
        )
    if room_columns and setpoint_columns and set(room_columns) != set(setpoint_columns):
        warnings.append(
            f"室温のゾーン {sorted(room_columns)} と設定温度のゾーン "
            f"{sorted(setpoint_columns)} が一致しない。対応づけを確認すること。"
        )

    positional = [k for k in list(room_columns) + list(setpoint_columns) if k.startswith("Z")]
    if positional:
        warnings.append(
            f"列名から方位を読み取れず、並び順で割り当てたゾーンがある: {sorted(set(positional))}。"
            "南東など向きに意味を持たせた分析をする前に、実際の方位を確認すること。"
        )

    if outdoor is not None and not outdoor.empty:
        outdoor_temp, outdoor_humidity = map_outdoor_columns(outdoor)
        mapping["外気温"] = outdoor_temp
        mapping["外気湿度"] = outdoor_humidity
        if not outdoor_temp:
            warnings.append("外気温列を特定できない。予冷時間モデルの説明変数が欠ける。")
        if not outdoor_humidity:
            warnings.append(
                "外気湿度列が無い。潜熱（除湿）負荷を考慮したモデル（06 / 07）は使えない。"
            )

    if power is not None and not power.empty:
        power_columns = find_power_columns(power)
        mapping["消費電力"] = {f"#{i + 1}": c for i, c in enumerate(power_columns)}
        if len(power_columns) == len(power.columns) and len(power_columns) > 2:
            warnings.append(
                f"電力列を名前で判別できず、数値列 {len(power_columns)} 本すべてを合計している。"
                "電力以外の列を巻き込んでいないか確認すること。"
            )
        if len(power_columns) != 2:
            warnings.append(
                f"電力列が {len(power_columns)} 本。チラー2台（A / B、30分の固定インターバル）"
                "を前提にした表示は、台数が違うとそのままでは合わない。"
            )

    return mapping, warnings


def check_period_overlap(frames: dict[str, pd.DataFrame]) -> list[str]:
    """ファイル間で期間が食い違っていないかを見る。"""
    spans = {
        name: (frame.index.min(), frame.index.max())
        for name, frame in frames.items()
        if frame is not None and not frame.empty
    }
    if len(spans) < 2:
        return []

    latest_start = max(s for s, _ in spans.values())
    earliest_end = min(e for _, e in spans.values())
    if latest_start >= earliest_end:
        return [
            "ファイル間で期間が重ならない。"
            + "; ".join(f"{n}: {s:%Y-%m-%d}〜{e:%Y-%m-%d}" for n, (s, e) in spans.items())
        ]

    warnings = []
    for name, (start, end) in spans.items():
        if start > latest_start or end < earliest_end:
            continue
    common_days = (earliest_end - latest_start).days + 1
    spans_text = "; ".join(f"{n}: {s:%Y-%m-%d}〜{e:%Y-%m-%d}" for n, (s, e) in spans.items())
    if len({(s.date(), e.date()) for s, e in spans.values()}) > 1:
        warnings.append(
            f"ファイルごとに期間が違う（{spans_text}）。"
            f"共通期間は {latest_start:%Y-%m-%d}〜{earliest_end:%Y-%m-%d} の {common_days} 日。"
            "分析はこの範囲でしか成立しない。"
        )
    return warnings


def check_dataset(
    power: pd.DataFrame | None,
    room: pd.DataFrame,
    outdoor: pd.DataFrame | None = None,
) -> tuple[pd.DataFrame, dict[str, dict], list[str]]:
    """3つの時系列をまとめて点検する。

    戻り値は (素性の表, 列マッピング, 警告の一覧)。
    """
    frames = {"消費電力": power, "室温・設定温度": room, "外気温・湿度": outdoor}
    kinds = {"消費電力": "power", "室温・設定温度": "room", "外気温・湿度": "outdoor"}

    reports = [
        describe_frame(name, frame, kinds[name])
        for name, frame in frames.items()
        if frame is not None
    ]

    warnings: list[str] = []
    for report in reports:
        warnings.extend(f"[{report.name}] {w}" for w in report.warnings)

    mapping, mapping_warnings = check_column_mapping(room, outdoor, power)
    warnings.extend(f"[列の解釈] {w}" for w in mapping_warnings)
    warnings.extend(f"[期間] {w}" for w in check_period_overlap(frames))

    if power is not None and not power.empty:
        warnings.extend(f"[起動検出] {w}" for w in check_startup_stability(power))

    return pd.DataFrame([r.as_row() for r in reports]), mapping, warnings

"""Open-Meteo連携の応答検証と失敗時の挙動。"""

from __future__ import annotations

import datetime as dt
import io
import json
from urllib.parse import parse_qs, urlparse

import pytest

from hvac.weather import (
    WeatherAPIError,
    WeatherLocation,
    fetch_hourly_forecast,
    search_locations,
)


def _opener(payload, captured=None):
    def open_response(url, timeout):
        if captured is not None:
            captured.update(url=url, timeout=timeout)
        return io.BytesIO(json.dumps(payload).encode())

    return open_response


def _location():
    return WeatherLocation(
        name="テスト市",
        latitude=34.7,
        longitude=135.5,
        timezone="Asia/Tokyo",
        admin1="大阪府",
        country="日本",
    )


def _forecast_payload(date_text="2026-08-28"):
    return {
        "timezone": "Asia/Tokyo",
        "hourly": {
            "time": [f"{date_text}T{hour:02d}:00" for hour in range(24)],
            "temperature_2m": [24.0 + hour / 10 for hour in range(24)],
            "relative_humidity_2m": [70.0 - hour / 2 for hour in range(24)],
        },
    }


def test_日本国内の地点候補を検索できる():
    captured = {}
    locations = search_locations(
        "テスト市",
        opener=_opener(
            {
                "results": [
                    {
                        "name": "テスト市",
                        "latitude": 34.7,
                        "longitude": 135.5,
                        "timezone": "Asia/Tokyo",
                        "admin1": "大阪府",
                        "country": "日本",
                    }
                ]
            },
            captured,
        ),
    )

    assert locations == [_location()]
    query = parse_qs(urlparse(captured["url"]).query)
    assert query["countryCode"] == ["JP"]
    assert query["language"] == ["ja"]
    assert captured["timeout"] == 10.0


def test_選択日の24時間予報と湿度を取得できる():
    captured = {}
    target = dt.date(2026, 8, 28)
    result = fetch_hourly_forecast(
        _location(),
        target,
        opener=_opener(_forecast_payload(), captured),
    )

    assert result.forecast_date == target
    assert len(result.forecast.temperatures) == 24
    assert result.forecast.temperature_at(5 * 60) == pytest.approx(24.5)
    assert result.forecast.humidity_at(5 * 60) == pytest.approx(67.5)
    query = parse_qs(urlparse(captured["url"]).query)
